            tg3_rrr(1, 2, 2) = tg3_rrr(1, 2, 2) + t_tg3_rrr_011
            tg3_rrr(2, 1, 2) = tg3_rrr(2, 1, 2) + t_tg3_rrr_011
            tg3_rrr(2, 2, 1) = tg3_rrr(2, 2, 1) + t_tg3_rrr_011
            t_tg3_rrr_012 = -v_a(1)*x95 - v_a(2)*x108 - v_a(3)*x110
            tg3_rrr(1, 2, 3) = tg3_rrr(1, 2, 3) + t_tg3_rrr_012
            tg3_rrr(1, 3, 2) = tg3_rrr(1, 3, 2) + t_tg3_rrr_012
            tg3_rrr(2, 1, 3) = tg3_rrr(2, 1, 3) + t_tg3_rrr_012
            tg3_rrr(2, 3, 1) = tg3_rrr(2, 3, 1) + t_tg3_rrr_012
            tg3_rrr(3, 1, 2) = tg3_rrr(3, 1, 2) + t_tg3_rrr_012
            tg3_rrr(3, 2, 1) = tg3_rrr(3, 2, 1) + t_tg3_rrr_012
            t_tg3_rrr_022 = -v_a(1)*x103 - v_a(2)*x110 - v_a(3)*x112
            tg3_rrr(1, 3, 3) = tg3_rrr(1, 3, 3) + t_tg3_rrr_022
            tg3_rrr(3, 1, 3) = tg3_rrr(3, 1, 3) + t_tg3_rrr_022
            tg3_rrr(3, 3, 1) = tg3_rrr(3, 3, 1) + t_tg3_rrr_022
            tg3_rrr(2, 2, 2) = &
               tg3_rrr(2, 2, 2) + (-v_a(1)*x106 - v_a(2)*(x117*x91 - x117*x93 + x118*x26 - &
               x118*x31 - x119*x67 + x119*x72 + 6.0_wp*x50 + x87) - v_a(3)*x116)
            t_tg3_rrr_112 = -v_a(1)*x108 - v_a(2)*x116 - v_a(3)*x121
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = -v_a(1)*x110 - v_a(2)*x121 - v_a(3)*x123
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = &
               tg3_rrr(3, 3, 3) + (-v_a(1)*x112 - v_a(2)*x123 - v_a(3)*(x124*x91 - x124*x93 + &
               x125*x26 - x125*x31 - x126*x67 + x126*x72 + 6.0_wp*x55 + x87))
         end block
      end select

   end subroutine cfc_atomic_tangent_eval

   pure module subroutine cfc_pair_tangent_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                         v_a, v_b, max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A v_A . d/dr_A of the order-0 spatial derivative
      real(wp), intent(inout) :: tg0
      !> sum_A v_A . d/dr_A of the order-1 spatial derivative
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A v_A . d/dr_A of the order-2 spatial derivative
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A v_A . d/dr_A of the order-3 spatial derivative
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         call cfc_pair_tangent_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                          v_a, v_b, max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr, sg_a, &
                                          sg_b)
         return
      end if

      ! Plateau: plain term, w = 1
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15

            x0 = 1.0_wp/R_a
            x1 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x2 = 1.0_wp/R_b
            x3 = sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x4 = c_par*exp(a2*(x0*x1 + x2*x3 - 2.0_wp))
            x5 = d_b(1)*x4
            x6 = x0*x2
            x7 = -x6*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
            x8 = 4.0_wp*x6*(x7*x7*x7)
            x9 = d_a(1)*x4
            x10 = a2*(x7*x7*x7*x7)
            x11 = x0*x10/x1
            x12 = x4*x8
            x13 = x11*x4
            x14 = x10*x2/x3
            x15 = x14*x4
            tg0 = &
               tg0 + (-v_a(1)*(x11*x9 - x5*x8) - v_a(2)*(d_a(2)*x13 - d_b(2)*x12) - &
               v_a(3)*(d_a(3)*x13 - d_b(3)*x12) - v_b(1)*(x14*x5 - x8*x9) - v_b(2)*(-d_a(2)*x12 + &
               d_b(2)*x15) - v_b(3)*(-d_a(3)*x12 + d_b(3)*x15))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = (d_a(1)*d_a(1))
            x4 = (d_a(2)*d_a(2))
            x5 = (d_a(3)*d_a(3))
            x6 = x3 + x4 + x5
            x7 = sqrt(x6)
            x8 = (d_b(1)*d_b(1))
            x9 = (d_b(2)*d_b(2))
            x10 = (d_b(3)*d_b(3))
            x11 = x10 + x8 + x9
            x12 = sqrt(x11)
            x13 = exp(a2*(x0*x7 + x1*x12 - 2.0_wp))
            x14 = c_par*x13
            x15 = x14*x2
            x16 = d_a(1)*d_b(1)
            x17 = d_a(2)*d_b(2)
            x18 = d_a(3)*d_b(3)
            x19 = -x2*(x16 + x17 + x18) + 1.0_wp
            x20 = (x19*x19*x19)
            x21 = 4.0_wp*x20
            x22 = x15*x21
            x23 = 1.0_wp/x7
            x24 = (x19*x19*x19*x19)
            x25 = x14*x24
            x26 = a2*x25
            x27 = x0*x26
            x28 = x23*x27
            x29 = 1.0_wp/x12
            x30 = x1*x26
            x31 = x29*x30
            x32 = 1.0_wp/(R_b*R_b)
            x33 = (x19*x19)
            x34 = 1.0_wp/(R_a*R_a)
            x35 = x14*x34
            x36 = 12.0_wp*x33*x35
            x37 = x32*x36
            x38 = d_b(2)*x37
            x39 = (a2*a2)
            x40 = x15*x23*x24*x29*x39
            x41 = d_a(2)*d_b(1)
            x42 = d_a(1)*d_a(2)
            x43 = a2*x21
            x44 = x1*x23*x35
            x45 = x43*x44
            x46 = d_b(1)*d_b(2)
            x47 = x0*x14*x29
            x48 = x43*x47
            x49 = x32*x48
            x50 = -x42*x45 - x46*x49
            x51 = d_a(1)*x38 + x40*x41 + x50
            x52 = d_b(3)*x37
            x53 = d_a(3)*d_b(1)
            x54 = d_a(1)*d_a(3)
            x55 = d_b(1)*d_b(3)
            x56 = -x45*x54 - x49*x55
            x57 = d_a(1)*x52 + x40*x53 + x56
            x58 = d_b(1)*x37
            x59 = d_a(1)*d_b(2)
            x60 = d_a(2)*x58 + x40*x59 + x50
            x61 = d_a(1)*d_b(3)
            x62 = d_a(3)*x58 + x40*x61 + x56
            x63 = x32*x8
            x64 = x27/(x6*sqrt(x6))
            x65 = 1.0_wp/x6
            x66 = x25*x39
            x67 = x34*x65*x66
            x68 = 8.0_wp*a2*x20
            x69 = x16*x68
            x70 = x30/(x11*sqrt(x11))
            x71 = 1.0_wp/x11
            x72 = x66*x71
            x73 = x32*x47
            x74 = d_a(1)*x45
            x75 = &
               c_par*d_a(1)*d_a(2)*x13*x24*x34*x39*x65 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*x13*x32*x33*x34 - d_b(2)*x74 - x41*x45 - x42*x64
            x76 = &
               c_par*d_a(1)*d_a(3)*x13*x24*x34*x39*x65 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*x13*x32*x33*x34 - d_b(3)*x74 - x45*x53 - x54*x64
            x77 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*x13*x32*x33*x34 + &
               c_par*d_b(1)*d_b(2)*x13*x24*x32*x39*x71 - x41*x49 - x46*x70 - x49*x59
            x78 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*x13*x32*x33*x34 + &
               c_par*d_b(1)*d_b(3)*x13*x24*x32*x39*x71 - x49*x53 - x49*x61 - x55*x70
            x79 = &
               c_par*d_a(1)*d_b(1)*x0*x1*x13*x23*x24*x29*x39 + &
               12.0_wp*c_par*d_a(1)*d_b(1)*x13*x32*x33*x34 - x22 - x3*x45 - x48*x63
            x80 = d_a(3)*d_b(2)
            x81 = d_a(2)*d_a(3)
            x82 = d_b(2)*d_b(3)
            x83 = -x45*x81 - x49*x82
            x84 = d_a(2)*x52 + x40*x80 + x83
            x85 = d_a(2)*d_b(3)
            x86 = d_a(3)*x38 + x40*x85 + x83
            x87 = x17*x68
            x88 = x32*x72
            x89 = &
               c_par*d_a(2)*d_a(3)*x13*x24*x34*x39*x65 + &
               12.0_wp*c_par*d_b(2)*d_b(3)*x13*x32*x33*x34 - x45*x80 - x45*x85 - x64*x81
            x90 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*x13*x32*x33*x34 + &
               c_par*d_b(2)*d_b(3)*x13*x24*x32*x39*x71 - x49*x80 - x49*x85 - x70*x82
            x91 = &
               c_par*d_a(2)*d_b(2)*x0*x1*x13*x23*x24*x29*x39 + &
               12.0_wp*c_par*d_a(2)*d_b(2)*x13*x32*x33*x34 - x22 - x4*x45 - x49*x9
            x92 = x18*x68
            x93 = &
               c_par*d_a(3)*d_b(3)*x0*x1*x13*x23*x24*x29*x39 + &
               12.0_wp*c_par*d_a(3)*d_b(3)*x13*x32*x33*x34 - x10*x49 - x22 - x45*x5
            tg0 = &
               tg0 + (-v_a(1)*(d_a(1)*x28 - d_b(1)*x22) - v_a(2)*(d_a(2)*x28 - d_b(2)*x22) - &
               v_a(3)*(d_a(3)*x28 - d_b(3)*x22) - v_b(1)*(-d_a(1)*x22 + d_b(1)*x31) - &
               v_b(2)*(-d_a(2)*x22 + d_b(2)*x31) - v_b(3)*(-d_a(3)*x22 + d_b(3)*x31))
            tg1_r(1) = &
               tg1_r(1) + (-v_a(1)*x79 - v_a(1)*(x28 - x3*x64 + x3*x67 + x36*x63 - x44*x69) - &
               v_a(2)*x51 - v_a(2)*x75 - v_a(3)*x57 - v_a(3)*x76 - v_b(1)*x79 - v_b(1)*(x3*x37 + &
               x31 + x63*x72 - x69*x73 - x70*x8) - v_b(2)*x60 - v_b(2)*x77 - v_b(3)*x62 - &
               v_b(3)*x78)
            tg1_r(2) = &
               tg1_r(2) + (-v_a(1)*x60 - v_a(1)*x75 - v_a(2)*x91 - v_a(2)*(x28 + x37*x9 - x4*x64 + &
               x4*x67 - x44*x87) - v_a(3)*x84 - v_a(3)*x89 - v_b(1)*x51 - v_b(1)*x77 - v_b(2)*x91 &
               - v_b(2)*(x31 + x37*x4 - x70*x9 - x73*x87 + x88*x9) - v_b(3)*x86 - v_b(3)*x90)
            tg1_r(3) = &
               tg1_r(3) + (-v_a(1)*x62 - v_a(1)*x76 - v_a(2)*x86 - v_a(2)*x89 - v_a(3)*x93 - &
               v_a(3)*(x10*x37 + x28 - x44*x92 - x5*x64 + x5*x67) - v_b(1)*x57 - v_b(1)*x78 - &
               v_b(2)*x84 - v_b(2)*x90 - v_b(3)*x93 - v_b(3)*(-x10*x70 + x10*x88 + x31 + x37*x5 - &
               x73*x92))
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
            real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104, x105
            real(wp) :: x106, x107, x108, x109, x110, x111, x112, x113, x114, x115, x116, x117, x118
            real(wp) :: x119, x120, x121, x122, x123, x124, x125, x126, x127, x128, x129, x130, x131
            real(wp) :: x132, x133, x134, x135, x136, x137, x138, x139, x140, x141, x142, x143, x144
            real(wp) :: x145, x146, x147, x148, x149, x150, x151, x152, x153, x154, x155, x156, x157
            real(wp) :: x158, x159, x160, x161, x162, x163, x164, x165, x166, x167, x168, x169, x170
            real(wp) :: x171, x172, x173, x174, x175, x176, x177, x178, x179, x180, x181, x182, x183
            real(wp) :: x184, x185, x186, x187, x188, x189, x190, x191, x192, x193, x194, x195, x196
            real(wp) :: x197, x198, x199, x200, x201, x202, x203, x204, x205, x206, x207, x208, x209
            real(wp) :: x210, x211, x212, x213, x214, x215, x216, x217, x218, x219, x220, x221, x222
            real(wp) :: x223, x224, x225, x226, x227, x228, x229, x230, x231, x232, x233, x234, x235
            real(wp) :: x236, x237, x238, x239, x240, x241, x242, x243, x244, x245, x246, x247, x248
            real(wp) :: x249, x250, x251, x252, x253, x254, x255, x256, x257, x258, x259, x260, x261
            real(wp) :: x262, x263, x264, x265, x266, x267, x268, x269, x270, x271, x272, x273, x274
            real(wp) :: x275, x276, x277, x278, x279, x280, x281, x282, x283, x284, x285, x286, x287
            real(wp) :: x288, x289, x290, x291, x292, x293, x294, x295, x296, x297, x298, x299, x300
            real(wp) :: x301, x302, x303, x304, x305, x306, x307, x308, x309, x310, x311, x312, x313
            real(wp) :: x314, x315, x316, x317, x318, x319, x320, x321, x322, x323, x324, x325, x326
            real(wp) :: x327, x328, x329, x330, x331, x332, x333, x334, x335, x336, x337, x338, x339
            real(wp) :: x340, x341, x342, x343, x344, x345, x346, x347, x348, x349, x350, x351, x352
            real(wp) :: x353, x354, x355, x356, x357, x358, x359, x360, x361, x362, x363, x364, x365
            real(wp) :: x366, x367, x368, x369, x370, x371, x372, x373, x374, x375, x376, x377, x378
            real(wp) :: x379, x380, x381, x382, x383, x384, x385, x386, x387, x388, x389, x390, x391
            real(wp) :: x392, x393, x394, x395, x396, x397, x398, x399, x400, x401, x402, x403, x404
            real(wp) :: x405, x406, x407, x408, x409, x410, x411, x412, x413, x414, x415, x416, x417
            real(wp) :: x418, x419, x420, x421, x422, x423, x424, x425, x426, x427, x428, x429, x430
            real(wp) :: x431, x432, x433, x434, x435, x436, x437, x438, x439, x440, x441, x442, x443
            real(wp) :: x444, x445, x446, x447, x448, x449, x450, x451, x452, x453, x454, x455, x456
            real(wp) :: x457, x458, x459, x460, x461, x462, x463, x464, x465, x466, x467
            real(wp) :: t_tg2_rr_01, t_tg2_rr_02, t_tg2_rr_12

            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = d_a(1)*d_b(1)
            x4 = d_a(2)*d_b(2)
            x5 = d_a(3)*d_b(3)
            x6 = -x2*(x3 + x4 + x5) + 1.0_wp
            x7 = (x6*x6*x6)
            x8 = (d_a(1)*d_a(1))
            x9 = (d_a(2)*d_a(2))
            x10 = (d_a(3)*d_a(3))
            x11 = x10 + x8 + x9
            x12 = sqrt(x11)
            x13 = (d_b(1)*d_b(1))
            x14 = (d_b(2)*d_b(2))
            x15 = (d_b(3)*d_b(3))
            x16 = x13 + x14 + x15
            x17 = sqrt(x16)
            x18 = exp(a2*(x0*x12 + x1*x17 - 2.0_wp))
            x19 = c_par*x18
            x20 = x19*x7
